// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/auth/register", wrapper.PostAuthRegister)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/auth/login", wrapper.PostAuthLogin)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/auth/logout", wrapper.PostAuthLogout)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/auth/switch", wrapper.PostAuthSwitch)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/auth/password", wrapper.PostAuthPassword)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/auth/forgot", wrapper.PostAuthForgot)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/auth/reset", wrapper.PostAuthReset)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/auth/verify", wrapper.PostAuthVerify)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/auth/verify/resend", wrapper.PostAuthVerifyResend)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/auth/session", wrapper.GetAuthSession)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/auth/name", wrapper.PutAuthName)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/auth/accounts/{uuid}", wrapper.DeleteAuthAccount)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/workspaces/members", wrapper.GetWorkspaceMembers)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/workspaces/switch", wrapper.PostWorkspaceSwitch)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/invitations", wrapper.CreateInvite)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/invitations/{uuid}", wrapper.RevokeInvite)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/invitations/{uuid}/accept", wrapper.AcceptInvite)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/invitations/{uuid}/decline", wrapper.DeclineInvite)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/workspaces", wrapper.ListWorkspaces)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/workspaces", wrapper.CreateWorkspace)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/workspaces/dissolve", wrapper.DissolveWorkspace)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/workspaces/leave", wrapper.LeaveWorkspace)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/workspaces/members/{id}", wrapper.RemoveWorkspaceMember)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/workspaces/members/{id}/role", wrapper.ChangeWorkspaceMemberRole)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/workspaces/name", wrapper.RenameWorkspace)
	})

	return r
}
